import{_ as i,o as n,c as u,a2 as t}from"./chunks/framework.CqpfiAoK.js";const l=JSON.parse('{"title":"Uunganisho wa Neo kati ya Ngazi","description":"","frontmatter":{},"headers":[],"relativePath":"sw/28-跨位面锚点连接.md","filePath":"sw/28-跨位面锚点连接.md"}'),o={name:"sw/28-跨位面锚点连接.md"};function k(h,a,w,s,e,g){return n(),u("div",null,[...a[0]||(a[0]=[t('<h1 id="uunganisho-wa-neo-kati-ya-ngazi" tabindex="-1">Uunganisho wa Neo kati ya Ngazi <a class="header-anchor" href="#uunganisho-wa-neo-kati-ya-ngazi" aria-label="Permalink to &quot;Uunganisho wa Neo kati ya Ngazi&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Mradi</th><th>Maudhui</th></tr></thead><tbody><tr><td>Nambari ya Hati</td><td>28</td></tr><tr><td>Moduli</td><td>Mfumo wa Neo na Kanuni za Usawa</td></tr><tr><td>Maneno Muhimu</td><td>Kati ya ngazi, Kituo cha ngazi, Uunganisho wa neo, Mtandao wa ulimwengu, Kizuizi cha ngazi</td></tr></tbody></table><h2 id="_1-dhana-na-umuhimu-wa-uunganisho-wa-neo-kati-ya-ngazi" tabindex="-1">1. Dhana na Umuhimu wa Uunganisho wa Neo kati ya Ngazi <a class="header-anchor" href="#_1-dhana-na-umuhimu-wa-uunganisho-wa-neo-kati-ya-ngazi" aria-label="Permalink to &quot;1. Dhana na Umuhimu wa Uunganisho wa Neo kati ya Ngazi&quot;">​</a></h2><p>Uunganisho wa neo kati ya ngazi unahusu kuanzisha njia za nishati na taarifa zenye utulivu kati ya neo za ngazi tofauti, na kumwezesha mtandao wa usawa kuvuka kizuizi cha ngazi kufikia uunganisho wa kote. Katika muundo wa ulimwengu wa Heng Yuan Zhou, ngazi ni vitengo vya nafasi-wakati vinavyojitegemea, na kila ngazi ina mfumo wake wa sheria, mazingira ya nishati, na aina za uhai. Kati ya ngazi kuna kile kinachojulikana kama &quot;kizuizi cha ngazi&quot; — kizuizi cha asili kilichoundwa na tofauti za sheria na kutengwa kwa nafasi-wakati, kinachofanya nishati na taarifa zisumbue kutiririka kwa uhuru kati ya ngazi.</p><p>Katika enzi ya mfumo wa uozi wa mauaji, kusafiri kati ya ngazi kulikuwa vigumu sana na hatari. Watu wachache tu wenye nguvu za juu walikuwa na uwezo wa kuteba kizuizi cha ngazi kwa nguvu zao wenyewe kusafiri, na kusafiri kwa namna hii mara nyingi kulihusisha matumizi makubwa ya nishati na hatari zisizoza kudhibitiwa. Uhai wa kawaida ulikuwa na uwezo mdogo sana wa kusafiri kati ya ngazi, na mawasiliano na ushirikiano kati ya ngazi kulikuwa bado hata kujadiliwa.</p><p>Baada ya kuanzishwa kwa utamaduni wa usawa wa neo, mapinduzi ya teknolojia ya uunganisho wa neo kati ya ngazi yamebadilisha hali hii kwa msingi. Kwa kuanzisha njia za uunganisho zenye utulivu kati ya neo za ngazi tofauti, utamaduni wa usawa umefikia:</p><ol><li><strong>Usambazaji wa nishati kati ya ngazi</strong>: ngazi zenye nishati zaidi zinaweza kutuma nishati kwa ngazi zenye upungufu wa nishati, na kufikia usawazishaji wa nishati wa kiwango cha ulimwengu</li><li><strong>Kushiriki taarifa kati ya ngazi</strong>: data za uozi, mafanikio ya teknolojia, na maarifa ya kitamaduni ya kila ngazi zinaweza kushirikiwa kwa wakati halisi, na kuongeza kasi ya mageuzi ya jumla</li><li><strong>Hamisha watu kati ya ngazi</strong>: uhai wa kawaida pia unaweza kufanya usafiri salama na thabiti kati ya ngazi kupitia njia ya neo</li><li><strong>Utawala wa pamoja kati ya ngazi</strong>: mfumo wa utawala wa utamaduni wa usawa unaweza kufunika ngazi zote zilizounganishwa, na kufikia utawala wa umoja wa kiwango cha ulimwengu</li><li><strong>Uchunguzi na kaleolojia kati ya ngazi</strong>: timu za uchunguzi zinaweza kufika kwa usalama katika ngazi zisizojulikana kupitia njia ya neo kufanya uchunguzi na kaleolojia</li></ol><p>Lengo la mwisho la uunganisho wa neo kati ya ngazi ni kuunganisha ngazi zote zinazofaa kwa uwepo wa uhai katika Heng Yuan Zhou katika mtandao wa usawa, na kuunda &quot;mtandao wa usawa wa ulimwengu&quot; unaofunika kote.</p><h2 id="_2-hali-ya-kweli-ya-kizuizi-cha-ngazi-na-kanuni-ya-kupenya" tabindex="-1">2. Hali ya Kweli ya Kizuizi cha Ngazi na Kanuni ya Kupenya <a class="header-anchor" href="#_2-hali-ya-kweli-ya-kizuizi-cha-ngazi-na-kanuni-ya-kupenya" aria-label="Permalink to &quot;2. Hali ya Kweli ya Kizuizi cha Ngazi na Kanuni ya Kupenya&quot;">​</a></h2><p>Ili kuelewa uunganisho wa neo kati ya ngazi, kwanza inahitajika kuelewa hali ya kweli ya kizuizi cha ngazi. Kizuizi cha ngazi sio kizuizi cha kimwili tu, bali ni kizuizi cha mchanganyiko kilichoundwa pamoja na tofauti katika viwango vitatu vifuatavyo:</p><table tabindex="0"><thead><tr><th>Kiwango cha kizuizi</th><th>Hali ya kweli</th><th>Ugumu wa kupenya</th><th>Njia ya kupenya</th></tr></thead><tbody><tr><td>Kizuizi cha nafasi-wakati</td><td>mratibu wa nafasi-wakati kati ya ngazi hauna mfululizo, kuna maporomoko ya nafasi-wakati</td><td>Juu</td><td>Teknolojia ya daraja la nafasi-wakati ya mfumo wa ratiba ya sheria ya nafasi</td></tr><tr><td>Kizuizi cha sheria</td><td>vigezo vya sheria ya asili ya ngazi tofauti vina tofauti, sheria hazilingani</td><td>Juu sana</td><td>Teknolojia ya ukadiriaji wa ulinganifu kati ya ngazi ya kiini cha sheria</td></tr><tr><td>Kizuizi cha nishati</td><td>aina na masafa ya nishati ya ngazi tofauti ni tofauti, nishati haiwezi kutiririka moja kwa moja</td><td>Kati</td><td>Teknolojia ya ubadilishaji wa nishati wa aina nyingi ya kiini cha nishati</td></tr></tbody></table><p>Kanuni ya msingi ya uunganisho wa neo kati ya ngazi ni, kupitia kazi ya ushirikiano wa viini vitatu vya neo (kiini cha sheria, kiini cha nishati, kiini cha taarifa), kupenya kwa pamoja kizuizi hizi za viwango vitatu, na kuanzisha njia thabiti kati ya ngazi mbili.</p><p>Kwa usahihi, mchakato wa kuanzisha uunganisho kati ya ngazi ni kama ifuatavyo:</p><ol><li><strong>Daraja la nafasi-wakati</strong>: kupitia mfumo wa ratiba ya sheria ya nafasi, kujenga daraja la nafasi-wakati kati ya neo za ngazi mbili, na kupenya kizuizi cha nafasi-wakati</li><li><strong>Ulinganifu wa sheria</strong>: kupitia ukadiriaji wa pande zote wa kiini cha sheria cha neo mbili, kufanya vigezo vya sheria vya mwisho wote kufikia hali ya ulinganifu, na kupenya kizuizi cha sheria</li><li><strong>Ubadilishaji wa nishati</strong>: kupitia viini vya nishati vya neo mbili, kuanzisha itifaki ya ubadilishaji wa nishati wa aina nyingi, na kufanya nishati iweze kutiririka kwa uhuru katika mwisho wote, na kupenya kizuizi cha nishati</li><li><strong>Usawazishaji wa taarifa</strong>: kupitia viini vya taarifa vya neo mbili, kuanzisha itifaki ya mawasiliano, na kufikia usawazishaji wa taarifa kwa wakati halisi</li><li><strong>Utulivu wa njia</strong>: baada ya viwango hivi vinne vya juu kupenwa, kuendelea kuchambua nishati thabiti, na kufanya njia iingie katika hali ya utendaji thabiti</li></ol><h2 id="_3-aina-na-viwango-vya-uunganisho-wa-neo-kati-ya-ngazi" tabindex="-1">3. Aina na Viwango vya Uunganisho wa Neo kati ya Ngazi <a class="header-anchor" href="#_3-aina-na-viwango-vya-uunganisho-wa-neo-kati-ya-ngazi" aria-label="Permalink to &quot;3. Aina na Viwango vya Uunganisho wa Neo kati ya Ngazi&quot;">​</a></h2><p>Kulingana na utulivu, upana wa njia, na matumizi ya uunganisho, uunganisho wa neo kati ya ngazi umegawanywa katika aina tatu zifuatavyo:</p><h3 id="_3-1-uunganisho-wa-msingi-wa-kudumu" tabindex="-1">3.1 Uunganisho wa msingi wa kudumu <a class="header-anchor" href="#_3-1-uunganisho-wa-msingi-wa-kudumu" aria-label="Permalink to &quot;3.1 Uunganisho wa msingi wa kudumu&quot;">​</a></h3><p>Uunganisho wa msingi wa kudumu unahusu njia ya uunganisho ya kudumu, yenye upana mkubwa wa njia, iliyoanzishwa kati ya neo za msingi za ngazi mbili. Uunganisho huu ni &quot;mtandao wa msingi&quot; wa mtandao kati ya ngazi, na unabeba kazi nyingi za usambazaji wa nishati na taarifa kati ya ngazi.</p><table tabindex="0"><thead><tr><th>Sifa</th><th>Kigezo</th></tr></thead><tbody><tr><td>Utulivu</td><td>thabiti kwa kudumu, muda wa wastani wa katiakatika kwa mwaka hauzidi saa 1</td></tr><tr><td>Upana wa njia wa nishati</td><td>mtiririko wa nishati wa kiwango cha ulimwengu (kila sekondi inaweza kusambaza nishati sawa na uzalishaji wa nishati wa mwaka wa sayari moja)</td></tr><tr><td>Upana wa njia wa taarifa</td><td>uingizwaji wa taarifa wa kiwango cha ulimwengu</td></tr><tr><td>Hamisha watu</td><td>inasaidia hamisha watu kwa kiwango kikubwa kwa pamoja</td></tr><tr><td>Gharama ya ujenzi</td><td>juu sana (inahitaji ujenzi wa ushirikiano wa watu wenye nguvu za juu wa ngazi nyingi, na hutumia rasilimali nadra nyingi)</td></tr><tr><td>Idadi</td><td>kila ngazi kwa kawaida ina uunganisho wa msingi wa kudumu wa 1-2 tu</td></tr></tbody></table><p>Ujenzi wa uunganisho wa msingi wa kudumu unahitaji mpango na idhini kali, na kwa kawaida unanzishwa tu kati ya ngazi zenye umuhimu mkubwa wa mkakati na mahitaji ya mawasiliano ya mara kwa mara.</p><h3 id="_3-2-uunganisho-wa-tawi-la-muda" tabindex="-1">3.2 Uunganisho wa tawi la muda <a class="header-anchor" href="#_3-2-uunganisho-wa-tawi-la-muda" aria-label="Permalink to &quot;3.2 Uunganisho wa tawi la muda&quot;">​</a></h3><p>Uunganisho wa tawi la muda unahusu njia ya uunganisho ya muda, yenye upana wa njia wa kati, iliyoanzishwa kati ya neo za kawaida za ngazi mbili. Uunganisho huu kwa kawaida hutumika kwa kazi mahususi (kama vile mawasiliano ya muda ya timu ya uchunguzi, usambazaji wa nishati wa dharura, hamisha watu kwa kiwango kidogo, n.k.), na inaweza kufungwa baada ya kazi kukamilika.</p><table tabindex="0"><thead><tr><th>Sifa</th><th>Kigezo</th></tr></thead><tbody><tr><td>Utulivu</td><td>thabiti kwa muda, inaweza kuendelea kutumika kwa siku kadhadhi hadi miezi kadhaa</td></tr><tr><td>Upana wa njia wa nishati</td><td>mtiririko wa nishati wa kiwango cha eneo la nyota</td></tr><tr><td>Upana wa njia wa taarifa</td><td>uingizwaji wa taarifa wa kiwango cha eneo la nyota</td></tr><tr><td>Hamisha watu</td><td>inasaidia hamisha watu kwa kiwango kidogo (kila mara haizidi watu 100)</td></tr><tr><td>Gharama ya ujenzi</td><td>kati (inahitaji msaada wa watu 1-2 wenye nguvu za juu wa ngazi)</td></tr><tr><td>Idadi</td><td>inanzishwa kwa nguvu kulingana na mahitaji, hakuna idadi thabiti</td></tr></tbody></table><p>Uanzishaji wa uunganisho wa tawi la muda ni rahisi kiasi, na unaweza kufungwa na kufungwa haraka kulingana na mahitaji ya kazi. Lakini kwa kuwa ni uunganisho wa muda, utulivu na usalama wake siyo sawa na uunganisho wa msingi wa kudumu, na wakati wa matumizi inahitajika kuzingatia kuzuia na kudhibiti hatari.</p><h3 id="_3-3-uunganisho-mdogo-wa-uchunguzi" tabindex="-1">3.3 Uunganisho mdogo wa uchunguzi <a class="header-anchor" href="#_3-3-uunganisho-mdogo-wa-uchunguzi" aria-label="Permalink to &quot;3.3 Uunganisho mdogo wa uchunguzi&quot;">​</a></h3><p>Uunganisho mdogo wa uchunguzi unahusu njia ya uunganisho yenye upana mdogo sana wa njia na matumizi ya nishati ya chini, iliyoanzishwa katika hatua ya kwanza ya uchunguzi wa ngazi isiyojulikana. Uunganisho huu hutumika hasa kuchunguza hali ya msingi ya ngazi isiyojulikana (vigezo vya sheria, mazingira ya nishati, aina za uhai, n.k.), na kutoa msaada wa data kwa uunganisho rasmi baadaye.</p><table tabindex="0"><thead><tr><th>Sifa</th><th>Kigezo</th></tr></thead><tbody><tr><td>Utulivu</td><td>hauthabiti kabisa, inaweza katiakatika wakati wowote</td></tr><tr><td>Upana wa njia wa nishati</td><td>chini sana (inafaa tu kudumisha uunganisho wenyewe)</td></tr><tr><td>Upana wa njia wa taarifa</td><td>upana mdogo wa njia (inaweza kusambaza data za msingi za uchunguzi tu)</td></tr><tr><td>Hamisha watu</td><td>haisaidi hamisha watu</td></tr><tr><td>Gharama ya ujenzi</td><td>chini kiasi (inaweza kukamilishwa na uchunguzi wa kiotomatiki)</td></tr><tr><td>Idadi</td><td>inaweza kuanzishwa kwa idadi kubwa wakati wa uchunguzi</td></tr></tbody></table><p>Uunganisho mdogo wa uchunguzi ni &quot;mwanasiasa&quot; wa uchunguzi kati ya ngazi, na kwa kuanzisha uunganisho mdogo wa uchunguzi kwa idadi kubwa, hali ya msingi ya ngazi isiyojulikana inaweza kueleweka haraka, na kutoa msingi kwa uunganisho rasmi na maendeleo baadaye.</p><h2 id="_4-usalama-na-utawala-wa-uunganisho-wa-neo-kati-ya-ngazi" tabindex="-1">4. Usalama na Utawala wa Uunganisho wa Neo kati ya Ngazi <a class="header-anchor" href="#_4-usalama-na-utawala-wa-uunganisho-wa-neo-kati-ya-ngazi" aria-label="Permalink to &quot;4. Usalama na Utawala wa Uunganisho wa Neo kati ya Ngazi&quot;">​</a></h2><p>Uunganisho kati ya ngazi, wakati unaleta urahisi mkubwa, pia umeleta hatari mpya za usalama na changamoto za utawala. Utamaduni wa usawa umeanzisha mfumo kamili wa usalama na utawala:</p><h3 id="_4-1-mfumo-wa-ulinzi-wa-usalama" tabindex="-1">4.1 Mfumo wa ulinzi wa usalama <a class="header-anchor" href="#_4-1-mfumo-wa-ulinzi-wa-usalama" aria-label="Permalink to &quot;4.1 Mfumo wa ulinzi wa usalama&quot;">​</a></h3><ol><li><strong>Usimbaji wa njia</strong>: njia zote kati ya ngazi zinatumia teknolojia ya usimbaji wa kiwango cha ulimwengu, na kuzuia nishati na taarifa kuibiwa au kubadilishwa</li><li><strong>Kugundua uingizaji</strong>: mfumo wa kugundua uingizaji umewekwa katika mwisho wote wa njia, na unafuatilia kwa wakati halisi ikiwa kuna kitu cha kibinadamu kisichoidhinishwa kinajaribu kupita njia</li><li><strong>Kuzuia na kutenga</strong>: watu, vitu, na nishati wanaoingia kutoka ngazi nyingine lazima wapite katika kuzuia na kutenga kali, na kuzuia hatari zisizojulikana (kama vile uhai wa ajabu, nishati ya ajabu, uchafuzi wa sheria, n.k.) kuingia katika ngazi yako</li><li><strong>Kukata kwa dharura</strong>: wakati njia inashambuliwa au inapata hali isiyo ya kawaida kali, njia inaweza kukatwa kwa dharura kwa kutumia mbali, na kuzuia hatari kuenea</li><li><strong>Njia ya nakala</strong>: uunganisho muhimu kati ya ngazi wote umeandaliwa na njia ya nakala, ambayo inaweza kubadilishwa haraka wakati njia kuu inashindwa</li></ol><h3 id="_4-2-mfumo-wa-sheria-za-utawala" tabindex="-1">4.2 Mfumo wa sheria za utawala <a class="header-anchor" href="#_4-2-mfumo-wa-sheria-za-utawala" aria-label="Permalink to &quot;4.2 Mfumo wa sheria za utawala&quot;">​</a></h3><ol><li><strong>Mfumo wa idhini ya uunganisho</strong>: kuanzisha uunganisho mpya kati ya ngazi lazima kupite katika idhini kali, na kutathmini hitaji, usalama, na athari zake</li><li><strong>Mfumo wa ruhusa ya kusafiri</strong>: watu wanaosafiri kupitia njia kati ya ngazi lazima waombe ruhusa ya kusafiri, na hawapaswi kusafiri kwa hiari zao bila ruhusa</li><li><strong>Mfumo wa ushuru wa rasilimali</strong>: nishati na rasilimali zinazosafirishwa kupitia njia kati ya ngazi zinahitaji kulipa &quot;ushuru wa usawazishaji kati ya ngazi&quot; kwa uwiano fulani, ambayo hutumika kwa matengenezo na usimamizi wa njia</li><li><strong>Mfumo wa uchunguzi wa taarifa</strong>: taarifa zinazosambazwa kupitia njia kati ya ngazi zinahitaji kupite katika uchunguzi wa usalama, na kuzuia uenezi wa taarifa zenye madhara (kama vile matangazo ya uadui wa mauaji, taarifa za uwongo, n.k.)</li><li><strong>Mfumo wa tahakimu ya mizozo</strong>: mizozo inayosababishwa na uunganisho kati ya ngazi (kama vile mizozo ya mgawanyo wa rasilimali, mizozo ya matumizi ya njia, n.k.) inahukumiwa na shirika la tahakimu la kiwango cha ulimwengu</li></ol><h2 id="_5-hatua-za-maendeleo-ya-uunganisho-kati-ya-ngazi" tabindex="-1">5. Hatua za Maendeleo ya Uunganisho kati ya Ngazi <a class="header-anchor" href="#_5-hatua-za-maendeleo-ya-uunganisho-kati-ya-ngazi" aria-label="Permalink to &quot;5. Hatua za Maendeleo ya Uunganisho kati ya Ngazi&quot;">​</a></h2><p>Maendeleo ya uunganisho wa neo kati ya ngazi yamegawanywa katika hatua tatu:</p><ol><li><strong>Hatua ya uunganisho wa majaribio</strong>: kuanzisha uunganisho wa msingi wa kudumu kati ya ngazi chache za msingi, na kuthibitisha uwezekano wa teknolojia na mfumo wa utawala</li><li><strong>Hatua ya uunganisho wa upanuzi</strong>: kupanua upeo wa uunganisho hadi ngazi nyingi zaidi zinazojulikana, na kuunda mtandao kati ya ngazi ulioanza kuwa na ukubwa</li><li><strong>Hatua ya uunganisho wa kote</strong>: kuunganisha ngazi zote zinazofaa kwa uwepo wa uhai katika mtandao wa usawa, na kuunda mtandao wa usawa wa ulimwengu unaofunika Heng Yuan Zhou kote</li></ol><p>Kwa sasa, Heng Yuan Zhou iko katika kipindi muhimu cha kubadilika kutoka hatua ya uunganisho wa majaribio hadi hatua ya uunganisho wa upanuzi, teknolojia ya uunganisho kati ya ngazi inakomaa kila mara, na upeo wa uunganisho unapanua polepole.</p><h2 id="hitimisho" tabindex="-1">Hitimisho <a class="header-anchor" href="#hitimisho" aria-label="Permalink to &quot;Hitimisho&quot;">​</a></h2><p>Uunganisho wa neo kati ya ngazi ni teknolojia ya msingi ya utamaduni wa usawa wa neo kwenda katika utamaduni wa ulimwengu. Kwa kupenya kizuizi cha ngazi na kuanzisha njia kati ya ngazi, utamaduni wa usawa umefikia mtiririko wa uhuru wa nishati, taarifa, na watu kwa kiwango cha ulimwengu, na kuweka msingi thabiti kwa maendeleo ya pamoja ya kila jinsia na kupandishwa kwa viwango vya ulimwengu. Pamoja na upanuzi wa kila mara wa uunganisho kati ya ngazi, Heng Yuan Zhou itabadilika kutoka ulimwengu wenye ngazi zilizotawanyika kuwa jumuiya ya usawa iliyounganishwa kwa kote.</p><h2 id="hati-zinazohusiana" tabindex="-1">Hati zinazohusiana <a class="header-anchor" href="#hati-zinazohusiana" aria-label="Permalink to &quot;Hati zinazohusiana&quot;">​</a></h2><ul><li>20-锚点结构与层级 (Muundo na Viwango vya Neo)</li><li>24-锚点能量传导路径 (Njia ya Mabadilisho ya Nishati ya Neo)</li><li>80-位面理论与分类 (Nadharia na Uainishaji wa Ngazi)</li></ul>',42)])])}const m=i(o,[["render",k]]);export{l as __pageData,m as default};
